import json
data = json.load(open('/app/resources/treasury_bulletin_1978_05.json'))
pages = data['document']['pages']
for i, page in enumerate(pages):
    elements = page.get('elements', [])
    for elem in elements:
        if isinstance(elem, dict) and 'text' in elem:
            if 'Total Treasury Notes' in elem['text'] and 'commercial banks' in elem['text']:
                print(f'Page {i}, text snippet:', elem['text'][:200])
                break
